# Retry: find a song from any of my Spotify playlists with release year 2020, then play it.

spotify_pw = [x['password'] for x in apis.supervisor.show_account_passwords() if x['account_name']=='spotify'][0]
login_resp = apis.spotify.login(username='jo.ball@gmail.com', password=spotify_pw)
access_token = login_resp['access_token']


def year_from_release_date(date_str):
    if date_str is None:
        return None
    s = str(date_str)
    if len(s) >= 4 and s[:4].isdigit():
        return int(s[:4])
    return None


def to_int_maybe(x):
    if x is None:
        return None
    try:
        return int(x)
    except Exception:
        return None


album_cache = {}  # album_id(int) -> year
song_cache = {}   # song_id(int) -> year

selected = None

page_index = 0
page_limit = 20

while True:
    playlists_page = apis.spotify.show_playlist_library(
        access_token=access_token,
        page_index=page_index,
        page_limit=page_limit
    )
    if not playlists_page:
        break

    for pl in playlists_page:
        playlist_id = to_int_maybe(pl.get('playlist_id'))
        playlist_title = pl.get('title')

        if playlist_id is None:
            continue

        playlist_detail = apis.spotify.show_playlist(
            playlist_id=playlist_id,
            access_token=access_token
        )

        for song in playlist_detail.get('songs', []):
            song_id = to_int_maybe(song.get('id'))
            if song_id is None:
                continue
            song_title = song.get('title')
            album_id = to_int_maybe(song.get('album_id'))
            album_title = song.get('album_title')
            artists = ', '.join([a['name'] for a in song.get('artists', []) if 'name' in a])

            # Album shortlist
            if album_id is not None:
                if album_id not in album_cache:
                    album_detail = apis.spotify.show_album(album_id=album_id)
                    album_cache[album_id] = year_from_release_date(album_detail.get('release_date'))
                album_year = album_cache[album_id]
            else:
                album_year = None

            if album_year != 2020:
                continue

            # Verify exact song release year
            if song_id not in song_cache:
                song_detail = apis.spotify.show_song(song_id=song_id)
                song_cache[song_id] = year_from_release_date(song_detail.get('release_date'))
            else:
                song_detail = apis.spotify.show_song(song_id=song_id)

            if song_cache[song_id] == 2020:
                selected = {
                    'playlist_title': playlist_title,
                    'song_title': song_title,
                    'artists': artists,
                    'album_title': album_title,
                    'song_id': song_id,
                    'album_id': album_id,
                    'song_release_date': song_detail.get('release_date'),
                    'song_release_year': song_cache[song_id]
                }
                break

        if selected:
            break

    if selected:
        break

    page_index += 1

print('Selected:' if selected else 'No selection', selected)
if selected:
    print('Verification table:')
    print('Title | Artists | Album | Playlist | Release Date')
    print(f"{selected['song_title']} | {selected['artists']} | {selected['album_title']} | {selected['playlist_title']} | {selected['song_release_date']}")
    print('Will play song_id:', selected['song_id'])
